package com.SpecificObjectHider;

import lombok.Data;
import lombok.EqualsAndHashCode;

@Data
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
public class HiddenObject
{
    @EqualsAndHashCode.Include
    private final int id;

    @EqualsAndHashCode.Include
    private final int x;

    @EqualsAndHashCode.Include
    private final int y;

    @EqualsAndHashCode.Include
    private final int plane;

    private final String name;

    // Excluded from equality so toggling active state doesn't break set lookups
    @EqualsAndHashCode.Exclude
    private boolean disabled = false;
}

package com.SpecificObjectHider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("specificobjecthider")
public interface SpecificObjectHiderConfig extends Config
{
	@ConfigItem(
			keyName = "showHideMenu",
			name = "Show Hide Option in Menu",
			description = "Adds 'Hide all options' to right-click menus on objects.",
			position = 1
	)
	default boolean showHideMenu()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showPanel",
			name = "Enable Side Panel",
			description = "Shows or hides the plugin side menu panel in the RuneLite sidebar.",
			position = 2
	)
	default boolean showPanel()
	{
		return true;
	}
}

package com.SpecificObjectHider;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.geom.Arc2D;
import java.awt.image.BufferedImage;

public class SpecificObjectHiderPanel extends PluginPanel
{
    private final SpecificObjectHiderPlugin plugin;
    private final JPanel listContainer = new JPanel();
    private boolean allRevealed = false;

    public SpecificObjectHiderPanel(SpecificObjectHiderPlugin plugin)
    {
        // RuneLite's PluginPanel natively handles scrolling automatically!
        super();

        this.plugin = plugin;

        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(10, 10, 10, 10));

        JPanel topPanel = new JPanel(new BorderLayout());
        topPanel.setBorder(new EmptyBorder(0, 0, 10, 0));

        JLabel title = new JLabel("Hidden Objects");
        title.setForeground(Color.WHITE);
        title.setFont(FontManager.getRunescapeFont());
        topPanel.add(title, BorderLayout.WEST);

        // Global Reveal All Icon Toggle Button (24x24 Eye)
        JButton revealAllBtn = new JButton(createEyeIcon(false, 24));
        revealAllBtn.setToolTipText("Toggle reveal all objects temporarily");
        revealAllBtn.setBorderPainted(false);
        revealAllBtn.setContentAreaFilled(false);
        revealAllBtn.setFocusPainted(false);
        revealAllBtn.setCursor(new Cursor(Cursor.HAND_CURSOR));

        revealAllBtn.addActionListener(e -> {
            allRevealed = !allRevealed;
            revealAllBtn.setIcon(createEyeIcon(allRevealed, 24));
            plugin.toggleAll(allRevealed);
        });

        topPanel.add(revealAllBtn, BorderLayout.EAST);
        add(topPanel, BorderLayout.NORTH);

        // Setup the list container
        listContainer.setLayout(new GridBagLayout());

        // Wrap it in a North-aligned BorderLayout to force items to stack cleanly at the top
        JPanel wrapperPanel = new JPanel(new BorderLayout());
        wrapperPanel.add(listContainer, BorderLayout.NORTH);

        // Add directly to the PluginPanel. The native RuneLite Scrollbar will handle overflow.
        add(wrapperPanel, BorderLayout.CENTER);

        updatePanel();
    }

    public void updatePanel()
    {
        SwingUtilities.invokeLater(() ->
        {
            listContainer.removeAll();

            GridBagConstraints gbc = new GridBagConstraints();
            gbc.fill = GridBagConstraints.HORIZONTAL;
            gbc.weightx = 1.0;
            gbc.gridx = 0;
            gbc.gridy = 0;
            gbc.insets = new Insets(0, 0, 5, 0);

            java.util.Set<HiddenObject> objects = plugin.getHiddenObjects();

            if (objects.isEmpty())
            {
                JLabel emptyLabel = new JLabel("No objects hidden.");
                emptyLabel.setFont(FontManager.getRunescapeSmallFont());
                emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                emptyLabel.setHorizontalAlignment(SwingConstants.CENTER);
                listContainer.add(emptyLabel, gbc);
            }
            else
            {
                for (HiddenObject obj : objects)
                {
                    listContainer.add(createObjectPanel(obj), gbc);
                    gbc.gridy++;
                }
            }

            listContainer.revalidate();
            listContainer.repaint();
        });
    }

    private JPanel createObjectPanel(HiddenObject obj)
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(new EmptyBorder(8, 8, 8, 8));

        JPanel textContainer = new JPanel();
        textContainer.setLayout(new BoxLayout(textContainer, BoxLayout.Y_AXIS));
        textContainer.setOpaque(false);

        String objName = obj.getName() != null && !obj.getName().isEmpty() ? obj.getName() : "Unknown Object";

        JLabel nameLabel = new JLabel(String.format("%s (%d)", objName, obj.getId()));
        nameLabel.setFont(FontManager.getRunescapeFont());
        nameLabel.setForeground(obj.isDisabled() ? Color.GRAY : Color.WHITE);

        JLabel locationLabel = new JLabel(String.format("Loc: %d, %d, P: %d", obj.getX(), obj.getY(), obj.getPlane()));
        locationLabel.setFont(FontManager.getRunescapeSmallFont());
        locationLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        textContainer.add(nameLabel);
        textContainer.add(Box.createRigidArea(new Dimension(0, 2)));
        textContainer.add(locationLabel);

        panel.add(textContainer, BorderLayout.CENTER);

        JPanel actionPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        actionPanel.setOpaque(false);

        JButton eyeBtn = new JButton(createEyeIcon(obj.isDisabled(), 16));
        eyeBtn.setToolTipText(obj.isDisabled() ? "Re-enable Block" : "Temporarily Reveal");
        eyeBtn.setBorderPainted(false);
        eyeBtn.setContentAreaFilled(false);
        eyeBtn.setFocusPainted(false);
        eyeBtn.setCursor(new Cursor(Cursor.HAND_CURSOR));
        eyeBtn.addActionListener(e -> plugin.toggleObject(obj));

        JButton trashBtn = new JButton(createTrashIcon(16));
        trashBtn.setToolTipText("Delete Object Block");
        trashBtn.setBorderPainted(false);
        trashBtn.setContentAreaFilled(false);
        trashBtn.setFocusPainted(false);
        trashBtn.setCursor(new Cursor(Cursor.HAND_CURSOR));

        trashBtn.addActionListener(e -> {
            JPopupMenu confirmMenu = new JPopupMenu();
            JLabel header = new JLabel("  Delete?  ");
            header.setFont(FontManager.getRunescapeFont());
            confirmMenu.add(header);
            confirmMenu.addSeparator();

            JMenuItem yesItem = new JMenuItem("Yes");
            yesItem.setFont(FontManager.getRunescapeSmallFont());
            yesItem.setForeground(Color.RED);
            yesItem.addActionListener(evt -> plugin.deleteObject(obj));

            JMenuItem noItem = new JMenuItem("No");
            noItem.setFont(FontManager.getRunescapeSmallFont());

            confirmMenu.add(yesItem);
            confirmMenu.add(noItem);
            confirmMenu.show(trashBtn, 0, trashBtn.getHeight());
        });

        actionPanel.add(eyeBtn);
        actionPanel.add(trashBtn);
        panel.add(actionPanel, BorderLayout.EAST);

        return panel;
    }

    private ImageIcon createEyeIcon(boolean isSlashed, int size)
    {
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        float opacity = isSlashed ? 0.45f : 1.0f;
        g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));

        g2.setColor(Color.LIGHT_GRAY);
        g2.setStroke(new BasicStroke(1.5f));
        g2.draw(new Arc2D.Float(1, size * 0.2f, size - 2, size * 0.6f, 0, 180, Arc2D.OPEN));
        g2.draw(new Arc2D.Float(1, size * 0.2f, size - 2, size * 0.6f, 180, 180, Arc2D.OPEN));

        g2.fillOval(size / 2 - 3, size / 2 - 3, 6, 6);

        if (isSlashed)
        {
            g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1.0f));
            g2.setColor(Color.YELLOW);
            g2.setStroke(new BasicStroke(2.0f));
            g2.drawLine(2, size - 3, size - 3, 2);
        }

        g2.dispose();
        return new ImageIcon(img);
    }

    private ImageIcon createTrashIcon(int size)
    {
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        g2.setColor(new Color(220, 60, 60));
        g2.setStroke(new BasicStroke(1.5f));

        g2.drawLine(2, 4, size - 3, 4);
        g2.drawRect(size / 2 - 2, 2, 4, 2);
        g2.drawRect(4, 5, size - 9, size - 7);

        g2.drawLine(7, 7, 7, size - 4);
        g2.drawLine(size / 2, 7, size / 2, size - 4);
        g2.drawLine(size - 8, 7, size - 8, size - 4);

        g2.dispose();
        return new ImageIcon(img);
    }
}

package com.SpecificObjectHider;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Text;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;

@Slf4j
@PluginDescriptor(
		name = "Specific Object Hider",
		description = "Hides all interaction options for specific object instances.",
		tags = {"hide", "objects", "options", "custom"}
)
public class SpecificObjectHiderPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "specificobjecthider";
	private static final String HIDDEN_OBJECTS_KEY = "hiddenObjectsList";

	@Inject
	private Client client;

	@Inject
	private SpecificObjectHiderConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Gson gson;

	@Getter
	private Set<HiddenObject> hiddenObjects = new HashSet<>();

	private SpecificObjectHiderPanel panel;
	private NavigationButton navButton;
	private boolean panelAdded = false;

	@Provides
	SpecificObjectHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpecificObjectHiderConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		loadHiddenObjects();
		panel = new SpecificObjectHiderPanel(this);

		navButton = NavigationButton.builder()
				.tooltip("Specific Object Hider")
				.icon(createThanosAnvilIcon())
				.priority(5)
				.panel(panel)
				.build();

		if (config.showPanel())
		{
			clientToolbar.addNavigation(navButton);
			panelAdded = true;
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (panelAdded)
		{
			clientToolbar.removeNavigation(navButton);
			panelAdded = false;
		}
		hiddenObjects.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(CONFIG_GROUP))
		{
			return;
		}

		if (event.getKey().equals("showPanel"))
		{
			if (config.showPanel() && !panelAdded)
			{
				clientToolbar.addNavigation(navButton);
				panelAdded = true;
			}
			else if (!config.showPanel() && panelAdded)
			{
				clientToolbar.removeNavigation(navButton);
				panelAdded = false;
			}
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.showHideMenu()) return;

		if (isObjectAction(event.getType()))
		{
			boolean alreadyHasHideOption = Arrays.stream(client.getMenuEntries())
					.anyMatch(e -> e.getOption().equals("Hide all options") && e.getIdentifier() == event.getIdentifier());

			if (!alreadyHasHideOption)
			{
				client.createMenuEntry(-1)
						.setOption("Hide all options")
						.setTarget(event.getTarget())
						.setIdentifier(event.getIdentifier())
						.setParam0(event.getActionParam0())
						.setParam1(event.getActionParam1())
						.setType(MenuAction.RUNELITE)
						.onClick(e -> hideObject(e, event.getTarget()));
			}
		}
	}

	private void hideObject(MenuEntry entry, String rawTarget)
	{
		WorldPoint wp = WorldPoint.fromScene(client, entry.getParam0(), entry.getParam1(), client.getPlane());
		String cleanName = Text.removeTags(rawTarget);

		HiddenObject obj = new HiddenObject(entry.getIdentifier(), wp.getX(), wp.getY(), wp.getPlane(), cleanName);

		hiddenObjects.remove(obj);
		hiddenObjects.add(obj);

		saveHiddenObjects();
		panel.updatePanel();
	}

	public void toggleObject(HiddenObject object)
	{
		object.setDisabled(!object.isDisabled());
		saveHiddenObjects();
		panel.updatePanel();
	}

	public void toggleAll(boolean disable)
	{
		for (HiddenObject obj : hiddenObjects)
		{
			obj.setDisabled(disable);
		}
		saveHiddenObjects();
		panel.updatePanel();
	}

	public void deleteObject(HiddenObject object)
	{
		hiddenObjects.remove(object);
		saveHiddenObjects();
		panel.updatePanel();
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.isMenuOpen()) return;
		filterMenuEntries();
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		filterMenuEntries();
	}

	private void filterMenuEntries()
	{
		if (hiddenObjects.isEmpty()) return;

		MenuEntry[] entries = client.getMenuEntries();
		java.util.List<MenuEntry> filtered = new ArrayList<>();
		boolean modified = false;

		for (MenuEntry entry : entries)
		{
			if (entry.getType() != null && isObjectAction(entry.getType().getId()))
			{
				WorldPoint wp = WorldPoint.fromScene(client, entry.getParam0(), entry.getParam1(), client.getPlane());
				HiddenObject check = new HiddenObject(entry.getIdentifier(), wp.getX(), wp.getY(), wp.getPlane(), "");

				for (HiddenObject hidden : hiddenObjects)
				{
					if (hidden.equals(check) && !hidden.isDisabled())
					{
						modified = true;
						check = null;
						break;
					}
				}

				if (check == null) continue;
			}
			filtered.add(entry);
		}

		if (modified)
		{
			client.setMenuEntries(filtered.toArray(new MenuEntry[0]));
		}
	}

	private boolean isObjectAction(int actionId)
	{
		return actionId == MenuAction.GAME_OBJECT_FIRST_OPTION.getId() ||
				actionId == MenuAction.GAME_OBJECT_SECOND_OPTION.getId() ||
				actionId == MenuAction.GAME_OBJECT_THIRD_OPTION.getId() ||
				actionId == MenuAction.GAME_OBJECT_FOURTH_OPTION.getId() ||
				actionId == MenuAction.GAME_OBJECT_FIFTH_OPTION.getId() ||
				actionId == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT.getId() ||
				actionId == MenuAction.EXAMINE_OBJECT.getId();
	}

	private void saveHiddenObjects()
	{
		String json = gson.toJson(hiddenObjects);
		configManager.setConfiguration(CONFIG_GROUP, HIDDEN_OBJECTS_KEY, json);
	}

	private void loadHiddenObjects()
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, HIDDEN_OBJECTS_KEY);
		if (json != null && !json.isEmpty())
		{
			Set<HiddenObject> loaded = gson.fromJson(json, new TypeToken<Set<HiddenObject>>() {}.getType());
			if (loaded != null) hiddenObjects.addAll(loaded);
		}
	}

	private BufferedImage createThanosAnvilIcon()
	{
		BufferedImage img = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g2 = img.createGraphics();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// 1. Solid Left Side of Anvil
		g2.setColor(new Color(110, 115, 125));
		g2.fillRect(6, 20, 10, 5);
		g2.fillRect(8, 14, 8, 6);
		g2.fillRect(4, 10, 12, 5);

		g2.setColor(new Color(160, 165, 175));
		g2.fillRect(4, 10, 12, 1);

		// 2. Fading/Dissolving Right Side
		g2.setColor(new Color(110, 115, 125, 160));
		g2.fillRect(16, 10, 5, 5);
		g2.fillRect(16, 20, 4, 5);

		g2.setColor(new Color(110, 115, 125, 80));
		g2.fillRect(21, 10, 4, 4);

		// 3. Floating Ashes & Embers
		Color ashGrey = new Color(170, 175, 185, 200);
		Color magicGold = new Color(255, 200, 50, 230);

		g2.setColor(ashGrey);
		g2.fillRect(22, 7, 2, 2);
		g2.fillRect(26, 12, 2, 2);
		g2.fillRect(24, 18, 2, 2);
		g2.fillRect(28, 8, 1, 1);

		g2.setColor(magicGold);
		g2.fillRect(20, 6, 2, 2);
		g2.fillRect(25, 15, 2, 2);
		g2.fillRect(27, 21, 2, 2);
		g2.fillRect(29, 11, 1, 1);

		g2.dispose();
		return img;
	}
}

